-- GENERATED by `wfj generate` from data/gossip/gossip-9e.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["9e02fba869ef2899"] = { "Vuoi imparare a usare un'arma, eh? Be', non startene lì a bocca aperta, parla, <ragazzo/ragazza>!", "." },
  ["9e0915ff3c926a5e"] = { "Non posso credere che a quei goblin avidi sia permesso di smerciare la loro roba rovinando lo spirito di questa stagione.", "." },
  ["9e092197d080093e"] = { "La Frostwolf Relief Hut si trova nella ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧, a sud delle Torri dei Lupi Bianchi.\n\nAl momento nessuna delle due parti la controlla.", "." },
  ["9e13a9021882f46a"] = { "Proprio così, <amico/amica>! La ⟦Darkmoon Faire=Fiera di Lunacupa⟧ si terrà proprio qui. Appena avrò scaricato quegli enormi carri, montato tutte le tende, allestito lo zoo e versato da bere. Non mancare di tornare!", "." },
  ["9e1ffa4c30eb4eac"] = { "Le ⟦Razorfen Kraul=Gallerie di Lamaspina⟧ si trovano all'estrema punta meridionale delle ⟦Barrens=Savane⟧, sul lato ovest della strada.", "." },
  ["9e25cbec59af1545"] = { "Hai un grande potenziale, ma prima devi raggiungere la comprensione: devi accettare gli spiriti e ascoltare il loro richiamo. Solo allora sarai <pronto/pronta> per il sentiero che devi seguire. Va' a parlare con Thrag: credo che possiate imparare molto l'uno dall'altro.", "." },
  ["9e3b040e636a5bfb"] = { "C'è solo una persona le cui abilità superano le mie. Ora puoi ricevere il suo sapere. Si chiama Annora, e puoi trovarla... a Uldaman.", "." },
  ["9e4598ac754bc040"] = { "È bello che tu voglia aiutare, {class}. Purtroppo ho già raccolto tutto il peacebloom che ci servirà per lo sforzo bellico. Magari potresti chiedere in giro: di sicuro qui c'è qualcun altro che ha ancora bisogno del tuo aiuto per raccogliere altre cose.", "." },
  ["9e507e253962bc87"] = { "Salve, {name}! Hai mai pensato di imparare un mestiere?\n\nSarò felice di rispondere a qualsiasi domanda tu abbia, o di indicarti gli istruttori della zona.\n\nSe ti sembra troppo, non preoccuparti! Puoi sempre tornare qui o visitare gli istruttori delle capitali per iniziare il tuo percorso di artigiano quando vuoi.", "." },
  ["9e5241b805094fd6"] = { "Allora... Credevi di potermi ingannare, eh? Me, la più grande mente criminale che Azeroth abbia mai conosciuto???", "." },
  ["9e52fde3944cd6e5"] = { "Che cos'è un ⟦Horde Commendation Signet=Anello d'Encomio dell'Orda⟧?", "." },
  ["9e54ca17dcda6e8d"] = { "Strapperò il frammento dal suo cadavere squarciato.", "." },
  ["9e5cbc8b42951657"] = { "Le ⟦The Deadmines=Miniere della Morte⟧ si trovano sotto ⟦Moonbrook=Rivoluna⟧, nel sud delle ⟦Westfall=Marche Occidentali⟧.", "." },
  ["9e606b7aebc08cde"] = { "Ti servono le mie abilità di alchimista, sì?", "." },
  ["9e6ffdbeaf4560b4"] = { "Se sei qui per cacciare draghi, fai pure. Dove devo mandare le mie condoglianze?", "." },
  ["9e7038409f389f5f"] = { "Avanti! E stavolta state in guardia! Non porterò sulle spalle altri combattimenti.", "." },
  ["9e72d87bcd5bc6d6"] = { "Che cosa mi porti da parte di Ashlan?", "." },
  ["9e748ed0499bd31f"] = { "È ora di incornare...", "." },
  ["9e7c3c7c45fc3c3e"] = { "La ⟦Darkmoon Faire=Fiera di Lunacupa⟧ si trova in questo momento nella ⟦Elwynn Forest=Foresta di Elwynn⟧, appena a sud di ⟦Goldshire=Borgodoro⟧. Non perdertela!", "." },
  ["9e7fc94d5b1e28c6"] = { "Stavo pensando la stessa cosa.", "." },
  ["9e872183ca0e7490"] = { "Non un pesce qualsiasi, mortale. Questo pesce era un pesciolino. Un pesciolino molto speciale.", "." },
  ["9e8c7f1f97c987aa"] = { "Dopo tutti questi anni di lotte, adesso si innamorano tutti!", "." },
  ["9e9352181da027cd"] = { "Come Teldrassil stessa, Dolanaar accoglie chi accoglie la terra.", "." },
  ["9e94da1a58d080a3"] = { "È stata una partenza bella movimentata, te lo dico io, {class}. Afferravamo tutto ciò che non era inchiodato o che si poteva portare via in fretta. Per questo siamo un po' a corto di scorte.", "." },
  ["9e9724bf4acb1424"] = { "Sì, corri! Così il sangue pompa più in fretta!", "." },
  ["9e99adcf662d3e62"] = { "Ah, l'occasione di usare questa lama appena affilata.", "." },
  ["9e9d1c0c62a88cff"] = { "Quel Granis Swiftaxe saprebbe bere più di un pesce, eppure la sua ascia colpisce ancora dritta. Comunque, se cerchi addestramento, faresti meglio a trovarlo finché riesci ancora a capire quello che dice.", "." },
  ["9ea30f0100610d14"] = { "Non ci posso credere, quel maledetto carro si è rotto. In questa terra non c'è un briciolo di fortuna. . . .", "." },
  ["9ea43558db576487"] = { "Assaggia la corruzione del tuo mondo!", "." },
  ["9eb1c58bf9618983"] = { "Ci vorrà solo un momento, {name}.", "." },
  ["9eb3c99142f7e230"] = { "Addio. Ci parleremo di nuovo, senz'altro.", "." },
  ["9eb5202a9f4d8276"] = { "<Mathredis fissa intensamente il libram.>\n\nSei qui per un'amalgama? Hai fatto ciò che il libram indicava?", "." },
  ["9ebbc7ac36008690"] = { "Basta così! Ci rivediamo alla base!", "." },
  ["9ebc72c6bc2b6791"] = { "Avanzi di verrospino! Dovrebbero fare al caso nostro. I pesci vanno matti per i verrospini.", "." },
  ["9ebdd7726a86e020"] = { "Costrizioni? Ci sono cose in questo mondo ben più costrittive di sbarre e catene, <signorino/signorina>. I non morti ci circondavano, tormentandoci di continuo con orribili atti di depravazione.\n\nAlla fine arrivò lui. Si presentò come il dottor Theolen Krastinov. Noi imparammo a conoscerlo come «il ⟦The Butcher=Macellaio⟧».", "." },
  ["9ec126c8f87fb050"] = { "Ti stai avvicinando... 7039 gradi Kraklenheit!", "." },
  ["9ec2ff048ce64d02"] = { "A causa dell'incompatibilità della tua specifica di classe, non sono in grado di aiutarti a rimediare a qualsiasi situazione tu abbia riguardo alla mancanza di abilità.", "." },
  ["9ec379161abb6138"] = { "Le forze dei Piccatonante ottengono l'⟦General's Warcry=Urlo di Guerra del Generale⟧.", "." },
  ["9ecc1faedb7fbe43"] = { "Abbiamo ordini diretti da Cairne, {race}. Non intralciare il compito del comandante.", "." },
  ["9ece08b033ed6461"] = { "<L'inquisitore supremo Fairbanks annuisce.>\n\nSì, il Mograine minore, quello noto come il Comandante Scarlatto, tramite (così sospetto) le trame del Gran Crociato. Ha condotto suo padre nell'imboscata come un agnello al macello.", "." },
  ["9ed27eb919146298"] = { "Qualcuno ha visto qualcosa? Che cos'è successo?", "." },
  ["9ed2d4aa4072b44a"] = { "%s solleva la sua enorme ascia sopra Grark.", "." },
  ["9eda8579d6317070"] = { "Non ne posso più di queste tasse! F.I.C.A. a me? F.I.C.A. a TE!", "." },
  ["9eda8ab4169c0aed"] = { "Hai dovuto insegnarle a non sporcare in casa, Gerard?", "." },
  ["9eed8e55e53851a7"] = { "Ho seguito le tracce dei vari frammenti del bastone in tutto il mondo e, così facendo, ho scoperto i piani di Kel'Thuzad per ricomporlo. Ha già raccolto diversi frammenti del bastone, custoditi dai suoi luogotenenti più fidati.\n\nNon potrò mai sottolineare abbastanza quanto sia importante tenere il Granbastone del Guardiano lontano dalle grinfie di Kel'Thuzad. Sinceramente non so quale sarebbe il risultato, se non una catastrofe di proporzioni epiche.", "." },
  ["9ef0022309174478"] = { "Guardiani! Difendete Sen'jin!", "." },
  ["9ef5491b516ab143"] = { "È questo il posto. Diamogli fuoco.", "." },
  ["9efd8ba135b5f04d"] = { "Milord, il vostro ospite è arrivato. Attende la vostra presenza.", "." },
})
